Here is the Python code to find the prime sequence and calculate their sum:

1. Generate a list of prime numbers using the Sieve of Eratosthenes.
2. Check for the arithmetic sequence with a common difference of 6.
3. Sum the prime numbers that form the sequence.

Let's implement this in Python.
```python
def sieve_of_eratosthenes(limit):
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for start in range(2, int(limit**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, limit + 1, start):
                is_prime[multiple] = False
    return [num for num, prime in enumerate(is_prime) if prime]

# Let's choose a sufficiently large limit to find the prime sequence
limit = 1000
primes = sieve_of_eratosthenes(limit)

# Now we look for the arithmetic sequence with a common difference of 6
prime_sequence = []
for i in range(len(primes)):
    for j in range(i + 1, len(primes)):
        if primes[j] - primes[i] == 6:
            # Check if we can form a sequence of length 5
            for k in range(j + 1, len(primes)):
                if primes[k] - primes[j] == 6:
                    for l in range(k + 1, len(primes)):
                        if primes[l] - primes[k] == 6:
                            for m in range(l + 1, len(primes)):
                                if primes[m] - primes[l] == 6:
                                    prime_sequence = [primes[i], primes[j], primes[k], primes[l], primes[m]]
                                    break
                    if prime_sequence:
                        break
                if prime_sequence:
                    break
            if prime_sequence:
                break
    if prime_sequence:
        break

# Sum of the prime numbers that form the sequence
prime_sum = sum(prime_sequence)
print((prime_sequence, prime_sum))
